(function(){'use strict';var state={results:null,history:[]};var elements={};

function init(){elements={input:document.getElementById('je-input'),output:document.getElementById('je-output'),escapeBtn:document.getElementById('escape-btn'),unescapeBtn:document.getElementById('unescape-btn'),resetBtn:document.getElementById('reset-btn'),emptyState:document.getElementById('empty-state'),statusBadge:document.getElementById('status-badge'),resultArea:document.getElementById('result-area'),exportSection:document.getElementById('export-section'),exportCopy:document.getElementById('export-copy'),exportTxt:document.getElementById('export-txt'),exportJson:document.getElementById('export-json'),exportPrint:document.getElementById('export-print'),comparisonSection:document.getElementById('comparison-section'),comparisonSelect:document.getElementById('comparison-select'),comparisonTable:document.getElementById('comparison-table'),historySection:document.getElementById('history-section'),historyList:document.getElementById('history-list'),statCharacters:document.getElementById('stat-characters'),statEscaped:document.getElementById('stat-escaped'),statOriginal:document.getElementById('stat-original'),statOutput:document.getElementById('stat-output'),statChange:document.getElementById('stat-change'),statDelta:document.getElementById('stat-delta')};
if(elements.escapeBtn)elements.escapeBtn.addEventListener('click',function(){process('escape');});
if(elements.unescapeBtn)elements.unescapeBtn.addEventListener('click',function(){process('unescape');});
if(elements.resetBtn)elements.resetBtn.addEventListener('click',reset);
if(elements.input)elements.input.addEventListener('input',onInput);
if(elements.exportCopy)elements.exportCopy.addEventListener('click',exportCopy);
if(elements.exportTxt)elements.exportTxt.addEventListener('click',exportTxt);
if(elements.exportJson)elements.exportJson.addEventListener('click',exportJson);
if(elements.exportPrint)elements.exportPrint.addEventListener('click',exportPrint);
if(elements.comparisonSelect)elements.comparisonSelect.addEventListener('change',onComparisonChange);
showEmptyState();}

function onInput(){if(elements.input&&elements.input.value.trim()){updateStatus('ready','Ready');}else{updateStatus('','');}}

function updateStatus(type,text){if(elements.statusBadge){elements.statusBadge.className='status-badge'+(type?' '+type:'');elements.statusBadge.textContent=text;}}

function showEmptyState(){if(elements.emptyState)elements.emptyState.style.display='flex';if(elements.resultArea)elements.resultArea.style.display='none';}

function showResults(){if(elements.emptyState)elements.emptyState.style.display='none';if(elements.resultArea){elements.resultArea.style.display='block';elements.resultArea.classList.add('show');}}

function escapeJSON(str){return JSON.stringify(str).slice(1,-1);}

function unescapeJSON(str){try{return JSON.parse('"'+str+'"');}catch(e){}try{return JSON.parse('"'+str.replace(/"/g,'\\"')+'"');}catch(e){}return str;}

function countEscapedChars(str){return(str.match(/[\n\r\t\b\f"\\]/g)||[]).length;}

function countEscapeSequences(str){return(str.match(/\\[nrtbf"\\]/g)||[]).length;}

function process(operation){if(!elements.input)return;var text=elements.input.value;if(!text.trim()){showEmptyState();return;}
updateStatus('processing','Processing...');
var t0=performance.now();
setTimeout(function(){var output;var escapedCount;if(operation==='escape'){output=escapeJSON(text);escapedCount=(output.match(/\\(.)/g)||[]).length;}else{output=unescapeJSON(text);escapedCount=(text.match(/\\[nrtbf"\\]/g)||[]).length;}
var chars=text.length;var originalSize=new Blob([text]).size;var outputSize=new Blob([output]).size;var change=outputSize-originalSize;var t1=performance.now();
var stats={operation:operation,inputText:text.substring(0,80)+(text.length>80?'...':''),outputText:output,chars:chars,escapedCount:escapedCount,originalSize:originalSize,outputSize:outputSize,change:change,time:t1-t0};
state.results=stats;if(state.history.length>=5)state.history.shift();state.history.push(stats);
var label=operation==='escape'?'Escaped':'Unescaped';
if(elements.output)elements.output.innerHTML='<div class="je-result"><span class="je-label">'+label+' Output</span><code class="je-code">'+escapeHtml(output)+'</code></div>';
if(elements.statCharacters)elements.statCharacters.textContent=chars;
if(elements.statEscaped)elements.statEscaped.textContent=escapedCount;
if(elements.statOriginal)elements.statOriginal.textContent=formatBytes(originalSize);
if(elements.statOutput)elements.statOutput.textContent=formatBytes(outputSize);
if(elements.statChange)elements.statChange.textContent=(change>=0?'+':'')+change;
if(elements.statDelta)elements.statDelta.textContent=(t1-t0)<1?'<1 ms':Math.round(t1-t0)+' ms';
var printTitle=document.querySelector('.print-report-title');var printDate=document.querySelector('.print-report-date');if(printTitle)printTitle.textContent='JSON Escape/Unescape Report';if(printDate)printDate.textContent='Generated on '+new Date().toLocaleString('en-US',{year:'numeric',month:'long',day:'numeric',hour:'2-digit',minute:'2-digit'});
updateStatus('done','Completed');
showResults();
if(elements.exportSection)elements.exportSection.style.display='flex';
renderComparison();renderHistory();},100);}

function exportCopy(){if(!state.results)return;var r=state.results;var op=r.operation==='escape'?'Escape':'Unescape';var text='JSON '+op+' Report\n====================\n\nOperation: '+op+'\nCharacters: '+r.chars+'\nEscaped Sequences: '+r.escapedCount+'\nInput Size: '+formatBytes(r.originalSize)+'\nOutput Size: '+formatBytes(r.outputSize)+'\nChange: '+(r.change>=0?'+':'')+r.change+' bytes\nProcessing Time: '+(r.time<1?'<1 ms':Math.round(r.time)+' ms')+'\n\nResult:\n'+r.outputText;
if(navigator.clipboard){navigator.clipboard.writeText(text.trim()).then(function(){showToast('Copied to clipboard!','success');});}else{fallbackCopy(text.trim());}}

function exportTxt(){if(!state.results)return;var r=state.results;var op=r.operation==='escape'?'Escape':'Unescape';var text='JSON '+op+' Report\n====================\n\nOperation: '+op+'\nCharacters: '+r.chars+'\nEscaped Sequences: '+r.escapedCount+'\nInput Size: '+formatBytes(r.originalSize)+'\nOutput Size: '+formatBytes(r.outputSize)+'\nChange: '+(r.change>=0?'+':'')+r.change+' bytes\nProcessing Time: '+(r.time<1?'<1 ms':Math.round(r.time)+' ms')+'\n\nResult:\n'+r.outputText;downloadFile('json-'+r.operation+'-report.txt',text,'text/plain');showToast('Downloaded TXT report','success');}

function exportJson(){if(!state.results)return;var r=state.results;var obj={operation:r.operation,timestamp:new Date().toISOString(),input:{text:r.inputText,characters:r.chars,sizeBytes:r.originalSize},output:{text:r.outputText,sizeBytes:r.outputSize},escapedSequences:r.escapedCount,changeBytes:r.change,processingTimeMs:Math.round(r.time)};var json=JSON.stringify(obj,null,2);downloadFile('json-'+r.operation+'-report.json',json,'application/json');showToast('Downloaded JSON report','success');}

function exportPrint(){window.print();}

function renderComparison(){if(!elements.comparisonSelect||!elements.comparisonTable)return;
var available=state.history.filter(function(item){return!state.results||item.inputText!==state.results.inputText;});
if(available.length===0||state.history.length<=1){if(elements.comparisonSection)elements.comparisonSection.style.display='none';return;}
if(elements.comparisonSection)elements.comparisonSection.style.display='block';
var html='<option value="">Select previous...</option>';
available.forEach(function(item,i){var idx=state.history.indexOf(item);
html+='<option value="'+idx+'">'+item.operation.charAt(0).toUpperCase()+item.operation.slice(1)+': '+item.inputText+' ('+item.chars+' chars)</option>';});
elements.comparisonSelect.innerHTML=html;}

function onComparisonChange(){var idx=parseInt(elements.comparisonSelect.value);
if(isNaN(idx)||!state.history[idx]||!state.results){elements.comparisonTable.innerHTML='';return;}
var prev=state.history[idx];var curr=state.results;
var metrics=[{label:'Operation',curr:curr.operation,prev:prev.operation},{label:'Characters',curr:curr.chars,prev:prev.chars},{label:'Input Size',curr:formatBytes(curr.originalSize),prev:formatBytes(prev.originalSize)},{label:'Output Size',curr:formatBytes(curr.outputSize),prev:formatBytes(prev.outputSize)},{label:'Escaped Sequences',curr:curr.escapedCount,prev:prev.escapedCount},{label:'Change (bytes)',curr:curr.change,prev:prev.change}];
var html='<table class="comparison-table"><thead><tr><th>Metric</th><th>Current</th><th>Previous</th><th>Change</th></tr></thead><tbody>';
metrics.forEach(function(m){var same=m.curr===m.prev;var diff=typeof m.curr==='number'&&typeof m.prev==='number'?m.curr-m.prev:0;
var arrow=!same&&typeof m.curr==='number'?(diff>0?'<span class="comp-up">+'+diff+'</span>':'<span class="comp-down">'+diff+'</span>'):'<span class="comp-same">0</span>';
html+='<tr><td>'+m.label+'</td><td>'+m.curr+'</td><td>'+m.prev+'</td><td>'+arrow+'</td></tr>';});
html+='</tbody></table>';elements.comparisonTable.innerHTML=html;}

function renderHistory(){if(!elements.historyList)return;
if(state.history.length<=1){if(elements.historySection)elements.historySection.style.display='none';return;}
if(elements.historySection)elements.historySection.style.display='block';
var html='';for(var i=state.history.length-1;i>=0;i--){var item=state.history[i];
var active=state.results&&item.inputText===state.results.inputText?' style="border-color:var(--color-primary);background:rgba(37,99,235,0.05)"':'';
var opLabel=item.operation==='escape'?'Escaped':'Unescaped';
html+='<div class="history-item"'+active+'><div class="history-meta"><span class="history-time">'+opLabel+'</span><span class="history-size">'+item.chars+' chars, '+formatBytes(item.originalSize)+'</span></div><div class="history-lines">'+item.escapedCount+' sequences, change '+(item.change>=0?'+':'')+item.change+' bytes</div></div>';}
elements.historyList.innerHTML=html;}

function downloadFile(filename,content,mimeType){var blob=new Blob([content],{type:mimeType});var url=URL.createObjectURL(blob);var a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();document.body.removeChild(a);URL.revokeObjectURL(url);}

function fallbackCopy(text){var ta=document.createElement('textarea');ta.style.cssText='position:fixed;opacity:0';ta.value=text;document.body.appendChild(ta);ta.select();try{document.execCommand('copy');showToast('Copied!','success');}catch(e){showToast('Failed to copy','error');}document.body.removeChild(ta);}

function reset(){if(elements.input)elements.input.value='';if(elements.output)elements.output.innerHTML='';state.results=null;state.history=[];if(elements.comparisonTable)elements.comparisonTable.innerHTML='';updateStatus('','');showEmptyState();if(elements.exportSection)elements.exportSection.style.display='none';if(elements.historySection)elements.historySection.style.display='none';if(elements.comparisonSection)elements.comparisonSection.style.display='none';}

function formatBytes(bytes){if(!bytes&&bytes!==0)return'0 B';if(bytes<1024)return bytes+' B';if(bytes<1048576)return(bytes/1024).toFixed(1)+' KB';return(bytes/1048576).toFixed(1)+' MB';}

function escapeHtml(str){if(typeof str!=='string')return'';return str.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}

function showToast(msg,type){var existing=document.querySelector('.toast');if(existing)existing.remove();var el=document.createElement('div');el.className='toast '+(type||'info');el.textContent=msg;document.body.appendChild(el);setTimeout(function(){el.classList.add('show');},10);setTimeout(function(){el.classList.remove('show');setTimeout(function(){el.remove();},300);},3000);}

if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',init);}else{init();}})();